head.b:skin:
/* Variable Definitions
====================
<Variable name="bg.color" description="خلفية الصفحة" type="color" default="#f8f6f1" value="#f8f6f1"/>
<Variable name="card.bg" description="خلفية البطاقات" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="primary.color" description="اللون الأساسي" type="color" default="#0e7c66" value="#0e7c66"/>
<Variable name="primary.dark" description="اللون الأساسي الداكن" type="color" default="#0a5d4c" value="#0a5d4c"/>
<Variable name="accent.color" description="لون التمييز" type="color" default="#c9962b" value="#c9962b"/>
<Variable name="text.color" description="لون النص" type="color" default="#1a1a1a" value="#1a1a1a"/>
<Variable name="muted.color" description="لون النص الثانوي" type="color" default="#6b6b6b" value="#6b6b6b"/>
<Variable name="border.color" description="لون الحدود" type="color" default="#e2ddd2" value="#e2ddd2"/>
<Variable name="header.bg" description="خلفية الرأس" type="color" default="#0e7c66" value="#0e7c66"/>
<Variable name="footer.bg" description="خلفية التذييل" type="color" default="#1a2e2a" value="#1a2e2a"/>
<Variable name="whatsapp.color" description="لون واتساب" type="color" default="#25d366" value="#25d366"/>
*/

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: 'Cairo', system-ui, -apple-system, 'Segoe UI', Tahoma, sans-serif;
  background: $(bg.color);
  color: $(text.color);
  line-height: 1.6;
  font-size: 16px;
  overflow-x: hidden;
}
a { color: $(primary.color); text-decoration: none; transition: color .2s ease; }
a:hover { color: $(primary.dark); }
img { max-width: 100%; height: auto; display: block; }
ul { list-style: none; }

/* ===== Layout ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 16px; }
.row { display: flex; flex-wrap: wrap; gap: 16px; }

/* ===== Header ===== */
.site-header {
  background: $(header.bg);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 12px rgba(0,0,0,.12);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 0;
  flex-wrap: wrap;
}
.site-logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 8px;
}
.site-logo:hover { color: #fff; opacity: .9; }
.site-logo .logo-icon {
  width: 36px; height: 36px;
  background: $(accent.color);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
}
.main-nav { display: flex; gap: 4px; flex-wrap: wrap; }
.main-nav a {
  color: rgba(255,255,255,.9);
  padding: 8px 14px;
  border-radius: 6px;
  font-size: .9rem;
  font-weight: 600;
  transition: background .2s ease;
}
.main-nav a:hover { background: rgba(255,255,255,.15); color: #fff; }
.nav-toggle {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  cursor: pointer;
  padding: 4px 8px;
}

/* ===== Search Bar ===== */
.search-bar {
  background: rgba(255,255,255,.1);
  border-radius: 8px;
  padding: 8px 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.search-bar input[type="text"] {
  background: transparent;
  border: none;
  color: #fff;
  font-size: .9rem;
  outline: none;
  width: 180px;
  font-family: inherit;
}
.search-bar input[type="text"]::placeholder { color: rgba(255,255,255,.6); }
.search-bar button {
  background: $(accent.color);
  border: none;
  color: #fff;
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  font-size: .85rem;
  font-weight: 600;
  font-family: inherit;
}

/* ===== Hero ===== */
.hero {
  background: linear-gradient(135deg, $(primary.color) 0%, $(primary.dark) 100%);
  color: #fff;
  padding: 60px 0 48px;
  text-align: center;
}
.hero h1 { font-size: 2.2rem; font-weight: 700; margin-bottom: 12px; }
.hero p { font-size: 1.1rem; opacity: .9; max-width: 700px; margin: 0 auto 24px; }
.hero-filters {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
  max-width: 700px;
  margin: 0 auto;
}
.hero-filters select, .hero-filters input {
  padding: 10px 14px;
  border: none;
  border-radius: 8px;
  font-size: .9rem;
  font-family: inherit;
  background: #fff;
  color: $(text.color);
}
.hero-filters button {
  background: $(accent.color);
  color: #fff;
  border: none;
  padding: 10px 24px;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  font-size: .9rem;
}

/* ===== Sections ===== */
.section { padding: 40px 0; }
.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 24px;
  color: $(primary.dark);
  display: flex;
  align-items: center;
  gap: 8px;
}
.section-title::after {
  content: '';
  flex: 1;
  height: 2px;
  background: $(border.color);
}

/* ===== Property Cards Grid ===== */
.property-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 20px;
}
.property-card {
  background: $(card.bg);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0,0,0,.06);
  transition: transform .2s ease, box-shadow .2s ease;
  display: flex;
  flex-direction: column;
}
.property-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(0,0,0,.12);
}
.property-card .card-image {
  width: 100%;
  height: 200px;
  object-fit: cover;
  background: $(border.color);
}
.property-card .card-body { padding: 16px; flex: 1; display: flex; flex-direction: column; }
.property-card .card-title {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 6px;
  color: $(text.color);
}
.property-card .card-meta {
  font-size: .85rem;
  color: $(muted.color);
  margin-bottom: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.property-card .card-meta span {
  background: $(bg.color);
  padding: 2px 8px;
  border-radius: 4px;
}
.property-card .card-price {
  font-size: 1.2rem;
  font-weight: 700;
  color: $(primary.color);
  margin-bottom: 4px;
}
.property-card .card-price-unit {
  font-size: .8rem;
  color: $(muted.color);
  font-weight: 400;
}
.property-card .card-id {
  font-size: .75rem;
  color: $(muted.color);
  margin-bottom: 12px;
}
.property-card .card-link {
  margin-top: auto;
  background: $(primary.color);
  color: #fff;
  text-align: center;
  padding: 10px;
  border-radius: 8px;
  font-weight: 600;
  font-size: .9rem;
  transition: background .2s ease;
}
.property-card .card-link:hover { background: $(primary.dark); color: #fff; }

/* ===== Fee Badge ===== */
.fee-note {
  font-size: .75rem;
  color: $(muted.color);
  padding: 6px 10px;
  background: #fff8e7;
  border: 1px solid #f0e0b0;
  border-radius: 6px;
  margin-bottom: 12px;
}

/* ===== Property Detail ===== */
.property-detail { padding: 40px 0; }
.property-detail .detail-header { margin-bottom: 24px; }
.property-detail .detail-title { font-size: 1.8rem; font-weight: 700; margin-bottom: 8px; }
.property-detail .detail-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}
.property-detail .detail-meta span {
  background: $(card.bg);
  border: 1px solid $(border.color);
  padding: 4px 12px;
  border-radius: 6px;
  font-size: .85rem;
}
.property-detail .detail-price {
  font-size: 1.6rem;
  font-weight: 700;
  color: $(primary.color);
}
.property-detail .detail-fee-disclosure {
  margin: 16px 0;
  padding: 12px 16px;
  background: #fff8e7;
  border-left: 4px solid $(accent.color);
  border-radius: 6px;
  font-size: .9rem;
  line-height: 1.7;
}

/* ===== Gallery ===== */
.gallery-container { margin-bottom: 24px; }
.gallery-main {
  width: 100%;
  border-radius: 12px;
  overflow: hidden;
  position: relative;
  background: $(border.color);
}
.gallery-main img {
  width: 100%;
  height: 400px;
  object-fit: cover;
}
.gallery-nav {
  display: flex;
  gap: 8px;
  margin-top: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
}
.gallery-thumb {
  width: 80px;
  height: 60px;
  object-fit: cover;
  border-radius: 6px;
  cursor: pointer;
  border: 2px solid transparent;
  flex-shrink: 0;
  transition: border-color .2s ease;
}
.gallery-thumb.active { border-color: $(primary.color); }
.gallery-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(0,0,0,.5);
  color: #fff;
  border: none;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  font-size: 1.2rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background .2s ease;
}
.gallery-btn:hover { background: rgba(0,0,0,.7); }
.gallery-btn.prev { left: 12px; }
.gallery-btn.next { right: 12px; }

/* ===== WhatsApp CTA ===== */
.whatsapp-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: $(whatsapp.color);
  color: #fff;
  padding: 12px 24px;
  border-radius: 10px;
  font-weight: 700;
  font-size: 1rem;
  transition: opacity .2s ease;
}
.whatsapp-cta:hover { opacity: .9; color: #fff; }
.whatsapp-note {
  font-size: .8rem;
  color: $(muted.color);
  margin-top: 8px;
}

/* ===== Inquiry Notice ===== */
.inquiry-notice {
  padding: 10px 16px;
  background: #fff3cd;
  border: 1px solid #ffc107;
  border-radius: 6px;
  font-size: .85rem;
  margin: 16px 0;
}

/* ===== Blog Posts (generic) ===== */
.post { background: $(card.bg); border-radius: 12px; padding: 24px; margin-bottom: 20px; box-shadow: 0 2px 8px rgba(0,0,0,.04); }
.post-title { font-size: 1.4rem; font-weight: 700; margin-bottom: 8px; }
.post-title a { color: $(text.color); }
.post-title a:hover { color: $(primary.color); }
.post-meta { font-size: .8rem; color: $(muted.color); margin-bottom: 16px; }
.post-body { line-height: 1.8; }
.post-body p { margin-bottom: 12px; }
.post-body h2, .post-body h3 { margin: 20px 0 10px; font-weight: 700; }
.post-body ul { padding-inline-start: 20px; list-style: disc; }
.post-body li { margin-bottom: 4px; }

/* ===== Pagination ===== */
.pagination { display: flex; justify-content: center; gap: 4px; padding: 24px 0; flex-wrap: wrap; }
.pagination a, .pagination span {
  padding: 8px 14px;
  border-radius: 6px;
  font-size: .9rem;
  font-weight: 600;
  border: 1px solid $(border.color);
  background: $(card.bg);
  color: $(text.color);
}
.pagination a:hover { background: $(primary.color); color: #fff; border-color: $(primary.color); }
.pagination .current-page { background: $(primary.color); color: #fff; border-color: $(primary.color); }

/* ===== Filter Labels Bar ===== */
.filter-bar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  padding: 16px 0;
  align-items: center;
}
.filter-bar .filter-label { font-weight: 600; font-size: .9rem; color: $(muted.color); }
.filter-bar .filter-chip {
  background: $(card.bg);
  border: 1px solid $(border.color);
  padding: 6px 14px;
  border-radius: 20px;
  font-size: .85rem;
  color: $(text.color);
  transition: all .2s ease;
}
.filter-bar .filter-chip:hover, .filter-bar .filter-chip.active {
  background: $(primary.color);
  color: #fff;
  border-color: $(primary.color);
}

/* ===== No Results / Loading ===== */
.no-results, .loading-state {
  text-align: center;
  padding: 40px;
  color: $(muted.color);
  font-size: 1.1rem;
}

/* ===== Sidebar Widgets ===== */
.sidebar { display: flex; flex-direction: column; gap: 20px; }
.widget-card {
  background: $(card.bg);
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 2px 8px rgba(0,0,0,.04);
}
.widget-card h3 { font-size: 1.1rem; font-weight: 700; margin-bottom: 12px; color: $(primary.dark); }
.widget-card ul li { padding: 6px 0; border-bottom: 1px solid $(border.color); font-size: .9rem; }
.widget-card ul li:last-child { border-bottom: none; }

/* ===== Ad Slot ===== */
.ad-slot {
  background: $(bg.color);
  border: 2px dashed $(border.color);
  border-radius: 8px;
  padding: 20px;
  text-align: center;
  color: $(muted.color);
  font-size: .85rem;
  min-height: 90px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ===== Footer ===== */
.site-footer {
  background: $(footer.bg);
  color: rgba(255,255,255,.8);
  padding: 40px 0 20px;
  margin-top: 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 24px;
  margin-bottom: 24px;
}
.footer-grid h4 { color: #fff; font-size: 1rem; font-weight: 700; margin-bottom: 12px; }
.footer-grid ul li { padding: 4px 0; }
.footer-grid ul li a { color: rgba(255,255,255,.7); font-size: .9rem; }
.footer-grid ul li a:hover { color: #fff; }
.footer-contact { font-size: .9rem; }
.footer-contact a { color: $(whatsapp.color); font-weight: 600; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.15);
  padding-top: 16px;
  text-align: center;
  font-size: .85rem;
  color: rgba(255,255,255,.5);
}

/* ===== RTL Adjustments ===== */
html[dir="rtl"] .gallery-btn.prev { left: auto; right: 12px; }
html[dir="rtl"] .gallery-btn.next { right: auto; left: 12px; }
html[dir="rtl"] .detail-fee-disclosure { border-left: none; border-right: 4px solid $(accent.color); }

/* ===== Responsive ===== */
@media (max-width: 768px) {
  .nav-toggle { display: block; }
  .main-nav {
    display: none;
    width: 100%;
    flex-direction: column;
    padding: 8px 0;
  }
  .main-nav.open { display: flex; }
  .main-nav a { width: 100%; }
  .search-bar { width: 100%; }
  .search-bar input[type="text"] { flex: 1; }
  .hero h1 { font-size: 1.6rem; }
  .hero p { font-size: 1rem; }
  .property-grid { grid-template-columns: 1fr; }
  .gallery-main img { height: 250px; }
  .footer-grid { grid-template-columns: 1fr; }
}
@media (min-width: 769px) and (max-width: 1024px) {
  .property-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ===== Reduced Motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
  html { scroll-behavior: auto; }
}

/* ===== Focus Visibility ===== */
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible {
  outline: 3px solid $(accent.color);
  outline-offset: 2px;
}

/* ===== Main Content Layout ===== */
.main-content { display: flex; gap: 24px; padding: 40px 0; }
.content-area { flex: 1; min-width: 0; }
.sidebar-area { width: 300px; flex-shrink: 0; }
@media (max-width: 768px) {
  .main-content { flex-direction: column; }
  .sidebar-area { width: 100%; }
}

/* ===== JSON-LD Structured Data ===== */
.structured-data { display: none; }

body.script:
//
(function() {
  // Gallery state
  var galleryImages = [];
  var currentIndex = 0;

  // Collect gallery images from post body
  function initGallery() {
    var body = document.querySelector('.post-body');
    if (!body) return;
    var imgs = body.querySelectorAll('img');
    var thumbsContainer = document.getElementById('gallery-thumbs');
    var mainImg = document.getElementById('gallery-main-img');
    if (!imgs.length || !thumbsContainer || !mainImg) return;

    galleryImages = [];
    imgs.forEach(function(img, i) {
      var src = img.src;
      galleryImages.push(src);
      // Hide original images in body
      img.style.display = 'none';

      // Create thumbnail
      var thumb = document.createElement('img');
      thumb.className = 'gallery-thumb';
      thumb.src = src;
      thumb.alt = 'صورة ' + (i + 1);
      thumb.setAttribute('onclick', 'gallerySelect(' + i + ')');
      thumb.setAttribute('role', 'button');
      thumb.setAttribute('tabindex', '0');
      thumb.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          gallerySelect(i);
        }
      });
      thumbsContainer.appendChild(thumb);
    });

    if (galleryImages.length > 0) {
      mainImg.src = galleryImages[0];
    }
  }

  // Gallery navigation
  window.galleryNav = function(direction) {
    if (galleryImages.length === 0) return;
    currentIndex += direction;
    if (currentIndex < 0) currentIndex = galleryImages.length - 1;
    if (currentIndex >= galleryImages.length) currentIndex = 0;
    updateGalleryMain();
  };

  window.gallerySelect = function(index) {
    currentIndex = index;
    updateGalleryMain();
  };

  function updateGalleryMain() {
    var mainImg = document.getElementById('gallery-main-img');
    if (!mainImg || !galleryImages[currentIndex]) return;
    mainImg.src = galleryImages[currentIndex];

    var thumbs = document.querySelectorAll('.gallery-thumb');
    thumbs.forEach(function(t, i) {
      t.classList.toggle('active', i === currentIndex);
    });
  }

  // Keyboard navigation for gallery
  document.addEventListener('keydown', function(e) {
    var main = document.querySelector('.gallery-main');
    if (!main) return;
    if (e.key === 'ArrowLeft') galleryNav(1);
    if (e.key === 'ArrowRight') galleryNav(-1);
  });

  // Hero filters
  window.applyHeroFilters = function() {
    var search = document.getElementById('hero-search');
    var type = document.getElementById('hero-type');
    var area = document.getElementById('hero-area');
    var baseUrl = window.location.origin + window.location.pathname;
    var query = [];

    if (search && search.value.trim()) {
      window.location.href = baseUrl + 'search?q=' + encodeURIComponent(search.value.trim());
      return;
    }
    if (type && type.value) query.push(type.value);
    if (area && area.value) query.push(area.value);

    if (query.length > 0) {
      window.location.href = baseUrl + 'search/label/' + encodeURIComponent(query.join('+'));
    } else {
      window.location.href = baseUrl;
    }
  };

  // Touch swipe for gallery
  (function() {
    var main = document.querySelector('.gallery-main');
    if (!main) return;
    var touchStartX = 0;
    main.addEventListener('touchstart', function(e) {
      touchStartX = e.touches[0].clientX;
    }, { passive: true });
    main.addEventListener('touchend', function(e) {
      var touchEndX = e.changedTouches[0].clientX;
      var diff = touchStartX - touchEndX;
      if (Math.abs(diff) > 50) {
        galleryNav(diff > 0 ? 1 : -1);
      }
    }, { passive: true });
  })();

  // Initialize on load
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initGallery);
  } else {
    initGallery();
  }
})();
//
